export function otaWorkoutDemos(program,week=1,day=1){
 const all=OTA_DEMO_CATALOG[program]??[];
 if(program==='ota-beginner')return (PAGES[program]?.['0:'+((Number(week)-1)*4+Number(day))]??[]).map(i=>all[i]);
 if(program==='ota-advanced')return all.filter(e=>e.sources.some(s=>s.phase===1&&s.page===4)&&/build.up.sprint/i.test(e.label));
 return []; // The selected Body Weight shuttle has no embedded demo hyperlink.
}
export function filterOtaDemos(program,query=''){
 const terms=String(query).toLowerCase().trim().split(/\s+/).filter(Boolean);
 return (OTA_DEMO_CATALOG[program]??[]).filter(e=>terms.every(term=>(e.label+' '+e.sources.map(s=>'Phase '+(s.phase??'')+' page '+s.page).join(' ')).toLowerCase().includes(term)));
}
export function renderOtaDemos({element:$,program,week,day,query=''}){
 const make=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;};
 const fill=(box,entries,provenance=false)=>{box.replaceChildren();for(const e of entries){const li=make('li'),a=make('a','',e.label+' ↗');a.href=e.url;a.target='_blank';a.rel='noopener noreferrer';li.append(a);if(provenance){const s=e.sources[0];li.append(make('small','field-help',(s.phase?'Phase '+s.phase+' · ':'')+'PDF page '+s.page));}box.append(li);}};
 const daily=otaWorkoutDemos(program,week,day);fill($('running-ota-demo-links'),daily);
 $('running-ota-demo-empty').hidden=Boolean(daily.length);
 const results=filterOtaDemos(program,query);fill($('running-ota-demo-library'),results,true);
 $('running-ota-demo-count').textContent=results.length+' of '+(OTA_DEMO_CATALOG[program]?.length??0)+' demo links';
}
